internal sealed class CreateElicitationRequestJsonConverter : JsonConverter<CreateElicitationRequest>
{
    public override CreateElicitationRequest? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return null;
        var obj = JsonNode.Parse(ref reader) as JsonObject ?? throw new JsonException("CreateElicitationRequest must be a JSON object.");
        var tag = AcpJson.GetTag(obj, "mode");
        return tag switch
        {
            "form" => obj.Deserialize(AcpJsonContext.Default.ElicitationFormMode),
            "url" => obj.Deserialize(AcpJsonContext.Default.ElicitationUrlMode),
            _ => new CreateElicitationRequest.Unknown(tag, obj),
        };
    }

    public override void Write(Utf8JsonWriter writer, CreateElicitationRequest value, JsonSerializerOptions options)
    {
        JsonNode? body = value switch
        {
            CreateElicitationRequest.Unknown u => u.Raw,
            ElicitationFormMode x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.ElicitationFormMode),
            ElicitationUrlMode x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.ElicitationUrlMode),
            _ => throw new JsonException($"Unsupported CreateElicitationRequest variant {value.GetType()}."),
        };
        AcpJson.WriteTagged(writer, "mode", value is CreateElicitationRequest.Unknown ? null : value.Tag, body);
    }
}

