        var obj = JsonNode.Parse(ref reader) as JsonObject ?? throw new JsonException("ElicitationPropertySchema must be a JSON object.");
        var tag = AcpJson.GetTag(obj, "type");
        return tag switch
        {
            "string" => obj.Deserialize(AcpJsonContext.Default.StringPropertySchema),
            "number" => obj.Deserialize(AcpJsonContext.Default.NumberPropertySchema),
            "integer" => obj.Deserialize(AcpJsonContext.Default.IntegerPropertySchema),
            "boolean" => obj.Deserialize(AcpJsonContext.Default.BooleanPropertySchema),
            "array" => obj.Deserialize(AcpJsonContext.Default.MultiSelectPropertySchema),
            _ => new ElicitationPropertySchema.Unknown(tag, obj),
        };
    }

    public override void Write(Utf8JsonWriter writer, ElicitationPropertySchema value, JsonSerializerOptions options)
    {
        JsonNode? body = value switch
        {
            ElicitationPropertySchema.Unknown u => u.Raw,
            StringPropertySchema x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.StringPropertySchema),
            NumberPropertySchema x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.NumberPropertySchema),
            IntegerPropertySchema x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.IntegerPropertySchema),
            BooleanPropertySchema x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.BooleanPropertySchema),
            MultiSelectPropertySchema x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.MultiSelectPropertySchema),
