internal sealed class SessionUpdateJsonConverter : JsonConverter<SessionUpdate>
{
    public override SessionUpdate? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return null;
        var obj = JsonNode.Parse(ref reader) as JsonObject ?? throw new JsonException("SessionUpdate must be a JSON object.");
        var tag = AcpJson.GetTag(obj, "sessionUpdate");
        return tag switch
        {
            "user_message_chunk" => obj.Deserialize(AcpJsonContext.Default.SessionUpdateUserMessageChunk),
            "agent_message_chunk" => obj.Deserialize(AcpJsonContext.Default.SessionUpdateAgentMessageChunk),
            "agent_thought_chunk" => obj.Deserialize(AcpJsonContext.Default.SessionUpdateAgentThoughtChunk),
            "tool_call" => obj.Deserialize(AcpJsonContext.Default.ToolCall),
            "tool_call_update" => obj.Deserialize(AcpJsonContext.Default.SessionUpdateToolCallUpdate),
            "plan" => obj.Deserialize(AcpJsonContext.Default.Plan),
            "available_commands_update" => obj.Deserialize(AcpJsonContext.Default.AvailableCommandsUpdate),
            "current_mode_update" => obj.Deserialize(AcpJsonContext.Default.CurrentModeUpdate),
            "config_option_update" => obj.Deserialize(AcpJsonContext.Default.ConfigOptionUpdate),
            "session_info_update" => obj.Deserialize(AcpJsonContext.Default.SessionInfoUpdate),
            "usage_update" => obj.Deserialize(AcpJsonContext.Default.UsageUpdate),
            "notice" => obj.Deserialize(AcpJsonContext.Default.Notice),
            "compaction_update" => obj.Deserialize(AcpJsonContext.Default.CompactionUpdate),
            "compaction_summary_chunk" => obj.Deserialize(AcpJsonContext.Default.CompactionSummaryChunk),
            _ => new SessionUpdate.Unknown(tag, obj),
        };
    }

    public override void Write(Utf8JsonWriter writer, SessionUpdate value, JsonSerializerOptions options)
    {
        JsonNode? body = value switch
        {
            SessionUpdate.Unknown u => u.Raw,
            SessionUpdateUserMessageChunk x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.SessionUpdateUserMessageChunk),
            SessionUpdateAgentMessageChunk x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.SessionUpdateAgentMessageChunk),
            SessionUpdateAgentThoughtChunk x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.SessionUpdateAgentThoughtChunk),
            ToolCall x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.ToolCall),
            SessionUpdateToolCallUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.SessionUpdateToolCallUpdate),
            Plan x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.Plan),
            AvailableCommandsUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.AvailableCommandsUpdate),
            CurrentModeUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.CurrentModeUpdate),
            ConfigOptionUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.ConfigOptionUpdate),
            SessionInfoUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.SessionInfoUpdate),
            UsageUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.UsageUpdate),
            Notice x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.Notice),
            CompactionUpdate x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.CompactionUpdate),
            CompactionSummaryChunk x => JsonSerializer.SerializeToNode(x, AcpJsonContext.Default.CompactionSummaryChunk),
            _ => throw new JsonException($"Unsupported SessionUpdate variant {value.GetType()}."),
        };
        AcpJson.WriteTagged(writer, "sessionUpdate", value is SessionUpdate.Unknown ? null : value.Tag, body);
    }
